function cleJour(ms){let d=ms===void 0?new Date:new Date(ms);return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}var aujourdhui=()=>cleJour();function semaineDe(d){let x=new Date(d),j=(x.getDay()+6)%7;return x.setDate(x.getDate()-j),x.setHours(0,0,0,0),x.getTime()}function dateFr(ms,annee){try{return new Date(ms).toLocaleDateString("fr-FR",annee?{day:"numeric",month:"long",year:"numeric"}:{day:"numeric",month:"long"})}catch{return""}}function jourFr(iso,avecJour){if(!iso)return"";let[a,m,j]=iso.split("-").map(Number);return new Date(a,m-1,j).toLocaleDateString("fr-FR",avecJour?{weekday:"long",day:"numeric",month:"long"}:{day:"numeric",month:"long"})}function dansCombien(iso){let[a,m,j]=iso.split("-").map(Number),[a0,m0,j0]=aujourdhui().split("-").map(Number),n=Math.round((new Date(a,m-1,j)-new Date(a0,m0-1,j0))/864e5);return n<0?"passé":n===0?"aujourd'hui":n===1?"demain":"dans "+n+" jours"}var dureeMin=m=>m>=60?Math.floor(m/60)+" h "+(m%60?String(m%60).padStart(2,"0"):""):m+" min";export{cleJour,aujourdhui,semaineDe,dateFr,jourFr,dansCombien,dureeMin};
